package io.xeros.solo;
import io.xeros.*;import io.xeros.content.miniquests.MageArena;import io.xeros.content.combat.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import java.util.*;
public final class MageArenaPlayableCheck {
 static void ok(boolean b,String s){BossesPlayableCheck.ok(b,s);}static Player actor(){Player p=BossRoutesCheck.actor();p.setLoginName("mage65qa");p.setDisplayName("Mage65qa");return p;}static void apply(Player p){BossesPlayableCheck.applied(p);p.teleTimer=0;}static NPC form(Player p){return p.getInstance().getNpcs().stream().filter(n->!n.isDead()&&!n.isUnregister()).findFirst().orElseThrow();}static void clear(Player p){if(p.getInstance()!=null)p.getInstance().remove(p);for(NPC n:new ArrayList<>(Arrays.asList(NPCHandler.npcs)))if(n!=null&&n.isUnregister())n.processDeregistration();BossesPlayableCheck.clear(p);}
 static void kill(Player p,NPC n){p.usingMagic=true;n.appendDamage(p,n.getHealth().getCurrentHealth(),Hitmark.HIT);ok(n.isDead(),"Mage form immune to Magic");for(int i=0;i<40&&!n.isUnregister()&&!n.needRespawn;i++)Server.npcHandler.getNpcProcess().process(n.getIndex());}
 static void complete(){Player p=actor();p.getMageArena().start();apply(p);ok(p.getInstance() instanceof MageArena.Arena,"Mage Arena entry");for(int i=0;i<5;i++){NPC n=form(p);ok(n.getNpcId()==1605+i,"Wrong Kolodion form "+i);p.usingMagic=false;int hp=n.getHealth().getCurrentHealth();n.appendDamage(p,10,Hitmark.HIT);ok(n.getHealth().getCurrentHealth()==hp,"Melee damaged Kolodion");kill(p,n);n.onDeath();if(i<4){ok(p.mageArenaStage==i+1,"Mage checkpoint");SkillsAuditCheck.tick(5);apply(p);}}ok(p.mageArenaCompleted&&p.mageArenaStage==0&&p.getInstance()==null,"Mage Arena completion");apply(p);ok(p.getMageArena().claimGodGear(0)&&p.getItems().getInventoryCount(2412)==1&&p.getItems().getInventoryCount(2415)==1,"Saradomin cape/staff");p.getMageArena().claimGodGear(0);ok(p.getItems().getInventoryCount(2415)==1,"Duplicate free staff");ok(PlayerSave.saveGameInstant(p),"Mage save");Player q=actor();ok(PlayerSave.loadGame(q,"mage65qa","IsolatedAudit",true).toString().equals("SUCCESS")&&q.mageArenaCompleted&&q.mageArenaStaffClaimed&&q.getItems().getInventoryCount(2415)==1&&q.getTeleportToX()==2538,"Mage Arena quest/reward persistence");clear(p);clear(q);System.out.println("MAGE_ARENA_FIVE_REAL_KOLODION_FORMS_MAGIC_ONLY_CHECKPOINTS_SINGLE_COMPLETION_GOD_CAPE_ONE_FREE_STAFF_AND_REAL_SAVE_RELOAD_PASS");}
 static void gear(){for(int god=0;god<3;god++){Player p=actor();p.mageArenaCompleted=true;BossRoutesCheck.at(p,2538,4716,0);p.teleTimer=0;if(god==2)while(p.getItems().freeSlots()>0)ok(p.getItems().addItem(526,1),"Full bag");ok(p.getMageArena().claimGodGear(god),"God choice "+god);ok(god==2?p.getItems().bankContains(2412+god)&&p.getItems().bankContains(2415+god):p.getItems().getInventoryCount(2412+god)==1&&p.getItems().getInventoryCount(2415+god)==1,"Wrong god prize "+god);clear(p);}System.out.println("MAGE_ARENA_ALL_THREE_GOD_CAPE_STAFF_CHOICES_AND_FULL_INVENTORY_BANK_PASS");}
 static void safety(){for(int i=0;i<5;i++){Player p=actor();if(i==0)p.isDead=true;if(i==1)p.getHealth().setCurrentHealth(0);if(i==2)p.teleTimer=2;if(i==3)p.isBanking=true;if(i==4)p.playerXP[6]=p.getPA().getXPForLevel(59)+1;p.getMageArena().start();ok(p.getInstance()==null,"Mage entry guard "+i);clear(p);}Player p=actor();ok(!p.getMageArena().claimGodGear(0),"Free cape before quest");p.getMageArena().start();apply(p);kill(p,form(p));ok(PlayerSave.saveGameInstant(p),"Mid quest save");Player q=actor();ok(PlayerSave.loadGame(q,"mage65qa","IsolatedAudit",true).toString().equals("SUCCESS")&&q.mageArenaStage==1&&!q.mageArenaCompleted&&q.getTeleportToX()==2538,"Mage checkpoint reload");clear(p);PlayerHandler.players[1]=q;q.getMageArena().start();apply(q);ok(form(q).getNpcId()==1606,"Mage resume form");q.isDead=true;q.getHealth().setCurrentHealth(0);io.xeros.content.combat.death.PlayerDeath.giveLife(q);ok(q.getInstance()==null&&q.mageArenaStage==0&&!q.mageArenaCompleted&&q.getHealth().getCurrentHealth()>0,"Mage death cleanup");clear(q);System.out.println("MAGE_ARENA_DEAD_ZERO_HP_BANK_TELEPORT_BASE_MAGIC_60_REQUIREMENT_EARLY_REWARD_GUARDS_MID_QUEST_RELOAD_AND_DEATH_RESET_PASS");}
 public static void main(String[]a)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;complete();gear();safety();System.out.println("MAGE_ARENA_I_PLAYABLE_V65_PASS");System.exit(0);}
}
